-- RideOn marketplace payment lifecycle.\n-- Accounting/reconciliation only; not a stored-value wallet or escrow account.\n\nALTER TABLE bookings\n  ADD COLUMN IF NOT EXISTS rental_amount_paise BIGINT NOT NULL DEFAULT 0 CHECK (rental_amount_paise >= 0),\n  ADD COLUMN IF NOT EXISTS vendor_amount_paise BIGINT NOT NULL DEFAULT 0 CHECK (vendor_amount_paise >= 0),\n  ADD COLUMN IF NOT EXISTS customer_total_paise BIGINT NOT NULL DEFAULT 0 CHECK (customer_total_paise >= 0),\n  ADD COLUMN IF NOT EXISTS settlement_eligible_at TIMESTAMPTZ;\n\nUPDATE bookings SET rental_amount_paise = COALESCE(rental_amount_paise,rental_total_paise), vendor_amount_paise = GREATEST(COALESCE(rental_total_paise,0)-COALESCE(platform_fee_paise,0),0), customer_total_paise = COALESCE(customer_total_paise,total_paise) WHERE rental_amount_paise=0 OR vendor_amount_paise=0 OR customer_total_paise=0;\n\nCREATE TABLE IF NOT EXISTS financial_transactions (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(), booking_id UUID NOT NULL REFERENCES bookings(id) ON DELETE RESTRICT, customer_id UUID REFERENCES customers(id) ON DELETE RESTRICT, vendor_id UUID REFERENCES vendors(id) ON DELETE RESTRICT, amount_paise BIGINT NOT NULL CHECK (amount_paise >= 0), currency VARCHAR(3) NOT NULL DEFAULT 'INR' CHECK (currency='INR'), transaction_type VARCHAR(40) NOT NULL, status VARCHAR(40) NOT NULL, provider VARCHAR(40) NOT NULL, provider_transaction_id VARCHAR(255), idempotency_key VARCHAR(128), failure_reason TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), completed_at TIMESTAMPTZ, settled_at TIMESTAMPTZ, refunded_at TIMESTAMPTZ\n);\nCREATE UNIQUE INDEX IF NOT EXISTS financial_transactions_provider_ref_idx ON financial_transactions(provider,provider_transaction_id) WHERE provider_transaction_id IS NOT NULL;\nCREATE INDEX IF NOT EXISTS financial_transactions_booking_idx ON financial_transactions(booking_id,created_at DESC);\n\nCREATE TABLE IF NOT EXISTS security_deposits (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(), booking_id UUID NOT NULL UNIQUE REFERENCES bookings(id) ON DELETE RESTRICT, customer_id UUID NOT NULL REFERENCES customers(id) ON DELETE RESTRICT, vendor_id UUID REFERENCES vendors(id) ON DELETE RESTRICT, original_amount_paise BIGINT NOT NULL CHECK (original_amount_paise >= 0), refundable_amount_paise BIGINT NOT NULL CHECK (refundable_amount_paise >= 0), approved_deduction_paise BIGINT NOT NULL DEFAULT 0 CHECK (approved_deduction_paise >= 0), status VARCHAR(40) NOT NULL DEFAULT 'pending', provider VARCHAR(40), provider_transaction_id VARCHAR(255), refund_provider_reference VARCHAR(255), deduction_reason TEXT, evidence_reference TEXT, dispute_status VARCHAR(40), idempotency_key VARCHAR(128), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), refunded_at TIMESTAMPTZ, CHECK (approved_deduction_paise <= original_amount_paise), CHECK (refundable_amount_paise + approved_deduction_paise = original_amount_paise)\n);\nCREATE INDEX IF NOT EXISTS security_deposits_status_idx ON security_deposits(status,updated_at DESC);\n\nCREATE TABLE IF NOT EXISTS vendor_settlements (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(), vendor_id UUID NOT NULL REFERENCES vendors(id) ON DELETE RESTRICT, booking_id UUID NOT NULL UNIQUE REFERENCES bookings(id) ON DELETE RESTRICT, gross_rental_amount_paise BIGINT NOT NULL CHECK (gross_rental_amount_paise >= 0), platform_fee_paise BIGINT NOT NULL CHECK (platform_fee_paise >= 0), adjustments_paise BIGINT NOT NULL DEFAULT 0 CHECK (adjustments_paise >= 0), net_settlement_amount_paise BIGINT NOT NULL CHECK (net_settlement_amount_paise >= 0), currency VARCHAR(3) NOT NULL DEFAULT 'INR' CHECK (currency='INR'), status VARCHAR(40) NOT NULL DEFAULT 'pending', provider_reference VARCHAR(255), failure_reason TEXT, initiated_at TIMESTAMPTZ, completed_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), CHECK (gross_rental_amount_paise >= platform_fee_paise + adjustments_paise), CHECK (net_settlement_amount_paise = gross_rental_amount_paise-platform_fee_paise-adjustments_paise)\n);\nCREATE INDEX IF NOT EXISTS vendor_settlements_vendor_status_idx ON vendor_settlements(vendor_id,status,created_at DESC);\n\nCREATE TABLE IF NOT EXISTS financial_transaction_events (id BIGSERIAL PRIMARY KEY, financial_transaction_id UUID NOT NULL REFERENCES financial_transactions(id) ON DELETE CASCADE, event_id VARCHAR(255) NOT NULL UNIQUE, previous_status VARCHAR(40), next_status VARCHAR(40) NOT NULL, payload_hash VARCHAR(128), created_at TIMESTAMPTZ NOT NULL DEFAULT now());\n